#!/usr/bin/env python3
"""Extract the actual MDX C++20 and verify literal, adaptive and symbolic oracles."""
from pathlib import Path
import json,os,re,shutil,subprocess,sys,tempfile
HARNESS = '\n#include <chrono>\n#include <climits>\n#include <cstdlib>\n#include <functional>\n#include <iostream>\n#include <map>\n#include <numeric>\n#include <random>\n#include <set>\n#include <tuple>\nusing U=std::uint64_t;\nU checks=0,static_cases=0,adaptive_states=0,adaptive_leaves=0,local_cases=0;\nU total_queries=0,total_lengths=0,checksum=0,budget_states=0;\nstd::size_t max_queries=0,max_length=0;\nstd::function<int(std::vector<int>)> grader;\nint use_machine(std::vector<int> x) { return grader(std::move(x)); }\nvoid require(bool condition,const char* why) {\n    ++checks;\n    if (!condition) { std::cerr<<"FAIL "<<why<<\'\\n\'; std::exit(1); }\n}\nstruct Observer {\n    int n; std::vector<unsigned> seen; unsigned calls=0; std::size_t length=0;\n    explicit Observer(int size):n(size),seen(size,0) {}\n    void inspect(const std::vector<int>& query) {\n        ++calls;length+=query.size();\n        require(query.size()>=2&&query.size()<=static_cast<std::size_t>(n),"query length is in original interval");\n        require(calls<=226&&length<=100000,"strict full-score query and total-length budgets");\n        for(int id:query) {\n            require(id>=0&&id<n,"query IDs in range");\n            require(seen[id]!=calls,"all query IDs are distinct");seen[id]=calls;\n        }\n    }\n};\n// Literal machine: compare the species attached to consecutive input IDs.\n// No decision-tree decoding or alternating-column formula occurs here.\nint literal(const std::vector<int>& species,const std::vector<int>& query) {\n    int changes=0;\n    for(std::size_t i=1;i<query.size();++i)changes+=species[query[i-1]]!=species[query[i]];\n    return changes;\n}\nstruct Cost { int queries=0,length=0; };\nstd::array<std::array<Cost,32>,2> cost;\nvoid local_trees() {\n    for(int mode=0;mode<2;++mode) {\n        std::set<std::string> visited;\n        int maximum_queries=0,maximum_length=0;\n        for(int reference=0;reference<2;++reference)for(unsigned mask=0;mask<32;++mask) {\n            const int first=mode?4:1,n=first+5;\n            std::array<std::vector<int>,2> known;\n            known[reference]=mode?std::vector<int>{0,1,2}:std::vector<int>{0};\n            if(mode)known[reference^1]={3};\n            std::vector<int> species(n,reference);\n            if(mode)species[3]=reference^1;\n            for(int bit=0;bit<5;++bit)species[first+bit]=reference^static_cast<int>((mask>>bit)&1u);\n            Observer observer(n);std::string history;\n            auto machine=[&](std::vector<int> query) {\n                visited.insert(history);observer.inspect(query);\n                const int response=literal(species,query);history.push_back(static_cast<char>(\'0\'+response));\n                return response;\n            };\n            const unsigned identified=transition_species_detail::identify_five(first,reference,known,machine);\n            require(identified==mask,"both local trees recover every literal five-bit assignment");\n            require(observer.calls<=static_cast<unsigned>(mode?2:3),"local worst query depth");\n            require(observer.length<=static_cast<unsigned>(mode?17:16),"local worst total query length");\n            maximum_queries=std::max(maximum_queries,static_cast<int>(observer.calls));\n            maximum_length=std::max(maximum_length,static_cast<int>(observer.length));\n            if(reference==0)cost[mode][mask]={static_cast<int>(observer.calls),static_cast<int>(observer.length)};\n            else require(cost[mode][mask].queries==static_cast<int>(observer.calls)&&cost[mode][mask].length==static_cast<int>(observer.length),"complement preserves decision cost");\n            ++local_cases;\n        }\n        if(mode)for(const auto& rule:transition_species_detail::mixed)require(visited.count(std::string(rule.history)),"every mixed tree query node is reached");\n        else for(const auto& rule:transition_species_detail::single)require(visited.count(std::string(rule.history)),"every single-anchor tree query node is reached");\n        require(maximum_queries==(mode?2:3)&&maximum_length==(mode?17:16),"local maxima actually attained");\n    }\n    require(cost[0][0].queries==1,"all equal initial group costs one query");\n}\nTwoSpeciesCount run_static(const std::vector<int>& species,bool adapter=false) {\n    const int n=static_cast<int>(species.size());require(species[0]==0,"original anchor is type A");\n    Observer observer(n);\n    auto machine=[&](std::vector<int> query) {observer.inspect(query);return literal(species,query);};\n    TwoSpeciesCount result;\n    if(adapter) {\n        grader=machine;const int answer=count_mushrooms(n);grader={};\n        result={answer,observer.calls,observer.length};\n    } else result=count_two_species_from_transition_queries(n,machine);\n    require(result.count_a==std::count(species.begin(),species.end(),0),"full count equals direct hidden species count");\n    require(result.queries==observer.calls&&result.total_query_length==observer.length,"reported query statistics match independent observer");\n    require(result.total_query_length<=40306,"proved stronger total length bound");\n    max_queries=std::max(max_queries,result.queries);max_length=std::max(max_length,result.total_query_length);\n    total_queries+=result.queries;total_lengths+=result.total_query_length;\n    checksum=checksum*1000003u+static_cast<U>(result.count_a)+result.queries*100003u+result.total_query_length;\n    ++static_cases;return result;\n}\nvoid all_static_small() {\n    for(int n=1;n<=17;++n)for(unsigned code=0;code<(1u<<(n-1));++code) {\n        std::vector<int> species(n,0);\n        for(int i=1;i<n;++i)species[i]=static_cast<int>((code>>(i-1))&1u);\n        run_static(species,n<=6);\n    }\n    require(static_cases==131071,"all binary species strings with anchor A up to length seventeen");\n}\nstruct NeedReply { std::vector<int> query; };\nvoid explore_adaptive(int n,std::vector<int>& replies,std::vector<std::vector<int>>& previous,\n                      const std::vector<unsigned>& possible) {\n    ++adaptive_states;Observer observer(n);std::size_t cursor=0;\n    auto machine=[&](std::vector<int> query) {\n        observer.inspect(query);\n        if(cursor==replies.size())throw NeedReply{std::move(query)};\n        require(query==previous[cursor],"adaptive replay preserves the complete query transcript");\n        return replies[cursor++];\n    };\n    try {\n        const auto result=count_two_species_from_transition_queries(n,machine);\n        require(cursor==replies.size()&&result.queries==replies.size(),"adaptive leaf consumes every previous reply");\n        for(unsigned mask:possible)require(result.count_a==n-std::popcount(mask),"all surviving adaptive worlds have the returned count");\n        ++adaptive_leaves;\n    } catch(const NeedReply& request) {\n        std::map<int,std::vector<unsigned>> buckets;\n        for(unsigned mask:possible) {\n            int changes=0;\n            for(std::size_t i=1;i<request.query.size();++i)\n                changes+=((mask>>request.query[i-1])&1u)!=((mask>>request.query[i])&1u);\n            buckets[changes].push_back(mask);\n        }\n        previous.push_back(request.query);\n        for(auto& [reply,worlds]:buckets) {\n            replies.push_back(reply);explore_adaptive(n,replies,previous,worlds);replies.pop_back();\n        }\n        previous.pop_back();\n    }\n}\nvoid all_adaptive_small() {\n    for(int n=2;n<=12;++n) {\n        std::vector<unsigned> possible;\n        for(unsigned code=0;code<(1u<<(n-1));++code)possible.push_back(code<<1);\n        std::vector<int> replies;std::vector<std::vector<int>> previous;\n        explore_adaptive(n,replies,previous,possible);\n    }\n}\nint bulk_worst(int a,int b,int remaining) {\n    int queries=0;\n    while(remaining>0) {\n        remaining-=std::min(remaining,std::max(a,b));++queries;\n        if(a<=b)++a;else ++b;\n    }\n    return queries;\n}\nstruct Parent {int a=-1,b=-1;unsigned mask=0;};\nvoid maximum_policy_witness() {\n    constexpr int limit=115;\n    std::vector<std::vector<int>> dp(limit,std::vector<int>(limit,-1));\n    std::vector<std::vector<Parent>> parent(limit,std::vector<Parent>(limit));\n    dp[1][0]=0;\n    for(int total=1;total<=216;total+=5)for(int a=0;a<limit;++a) {\n        const int b=total-a;if(b<0||b>=limit||dp[a][b]<0)continue;\n        ++budget_states;if(std::max(a,b)>=110)continue;\n        const int reference=a>=b?0:1;\n        const int mode=std::max(a,b)>=3&&std::min(a,b)>=1?1:0;\n        for(unsigned mask=0;mask<32;++mask) {\n            const int opposite=std::popcount(mask);\n            const int aa=a+(reference?opposite:5-opposite),bb=b+(reference?5-opposite:opposite);\n            require(aa<limit&&bb<limit,"complete abstract training state range");\n            const int value=dp[a][b]+cost[mode][mask].queries;\n            if(value>dp[aa][bb]) {dp[aa][bb]=value;parent[aa][bb]={a,b,mask};}\n        }\n    }\n    int best=-1,best_a=-1,best_b=-1;\n    for(int a=0;a<limit;++a)for(int b=0;b<limit;++b)if(dp[a][b]>=0&&std::max(a,b)>=110) {\n        const int value=dp[a][b]+bulk_worst(a,b,20000-a-b);\n        require(value<=226,"all reachable maximal-input abstract policies respect full score");\n        if(value>best) {best=value;best_a=a;best_b=b;}\n    }\n    require(best==226,"exact worst-case 226 queries is attained by a consistent policy");\n    std::vector<std::tuple<int,unsigned>> steps;\n    for(int a=best_a,b=best_b;a!=1||b!=0;) {\n        const auto prev=parent[a][b];require(prev.a>=0,"maximal-policy predecessor exists");\n        steps.push_back({prev.a>=prev.b?0:1,prev.mask});a=prev.a;b=prev.b;\n    }\n    std::reverse(steps.begin(),steps.end());std::vector<int> species(20000,-1);species[0]=0;\n    int first=1;\n    for(auto [reference,mask]:steps) {\n        for(int bit=0;bit<5;++bit)species[first+bit]=reference^static_cast<int>((mask>>bit)&1u);\n        first+=5;\n    }\n    require(first==best_a+best_b,"training witness has the abstract known total");\n    int a=best_a,b=best_b;Observer observer(20000);\n    auto adversary=[&](std::vector<int> query) {\n        observer.inspect(query);\n        bool fresh=false;for(int index:query)fresh|=species[index]<0;\n        if(fresh) {\n            require(query.size()%2==0&&species[query[1]]>=0,"bulk witness is alternating with known anchors");\n            const int endpoint=a<=b?0:1,reference=species[query[1]];\n            for(std::size_t i=0;i<query.size();i+=2) {\n                require(species[query[i]]<0&&species[query[i+1]]==reference,"bulk witness uses fresh unknowns and one anchor type");\n                species[query[i]]=i==0?endpoint:reference;\n            }\n            if(endpoint==0)++a;else ++b;\n        }\n        return literal(species,query);\n    };\n    const auto result=count_two_species_from_transition_queries(20000,adversary);\n    require(std::none_of(species.begin(),species.end(),[](int x){return x<0;}),"adaptive worst witness materializes every species");\n    require(result.queries==226&&observer.calls==226,"maximal adaptive witness realizes 226 actual calls");\n    require(result.count_a==std::count(species.begin(),species.end(),0),"maximal adaptive witness direct answer");\n    const auto fixed=run_static(species);\n    require(fixed.queries==226&&fixed.count_a==result.count_a,"materialized worst transcript also works as a fixed oracle");\n    for(int t=22;t<=44;++t) {\n        const int total=1+5*t,q=225-2*t;int capacity=0;\n        for(int j=0;j<q;++j)capacity+=std::max(110,(total+j+1)/2);\n        require(capacity>=20000-total&&2*t+1+q==226,"exact integer capacity certificate for every training length");\n        const int margin=t==44?52:(9*t*t-824*t+19040)/4;\n        require(capacity-(20000-total)==margin&&margin>=52,"independent closed-form capacity margin");\n    }\n}\nvoid large_patterns() {\n    std::mt19937 rng(0x20200919);\n    for(int n:{1,2,5,6,109,110,111,215,216,217,220,221,222,225,226,227,19999,20000}) {\n        std::vector<int> species(n,0);run_static(species);\n        for(int i=1;i<n;++i)species[i]=1;\n        run_static(species);\n        for(int i=1;i<n;++i)species[i]=i&1;\n        run_static(species);\n        for(int i=1;i<n;++i)species[i]=i<151?0:static_cast<int>((i/7)&1);\n        run_static(species);\n    }\n    for(int sample=0;sample<160;++sample) {\n        const int n=sample<80?20000:1+static_cast<int>(rng()%20000);std::vector<int> species(n,0);\n        for(int i=1;i<n;++i)species[i]=static_cast<int>(rng()&1u);\n        run_static(species,sample<4);\n    }\n}\nint invalid_cases=0;\nvoid invalid_inputs() {\n    int callback_calls=0;\n    for(int n:{0,-1,20001,INT_MIN,INT_MAX}) {\n        bool rejected=false;\n        try{(void)count_two_species_from_transition_queries(n,[&](std::vector<int>){++callback_calls;return 0;});}\n        catch(const std::invalid_argument&){rejected=true;}\n        require(rejected&&callback_calls==0,"invalid n rejected before any machine call");++invalid_cases;\n    }\n    for(int reply:{-1,INT_MIN,INT_MAX,6}) {\n        bool rejected=false;\n        try{(void)count_two_species_from_transition_queries(6,[&](std::vector<int>){return reply;});}\n        catch(const std::runtime_error&){rejected=true;}\n        require(rejected,"out-of-range machine reply rejected");++invalid_cases;\n    }\n    bool inconsistent=false;int index=0;\n    try{(void)count_two_species_from_transition_queries(6,[&](std::vector<int>){return index++==0?2:3;});}\n    catch(const std::runtime_error&){inconsistent=true;}\n    require(inconsistent&&index==2,"range-valid but locally impossible reply rejected");++invalid_cases;\n    bool propagated=false;\n    try{(void)count_two_species_from_transition_queries(2,[](std::vector<int>)->int{throw std::domain_error("oracle stopped");});}\n    catch(const std::domain_error&){propagated=true;}\n    require(propagated,"machine callback exception propagates");++invalid_cases;\n    const auto one=count_two_species_from_transition_queries(1,[&](std::vector<int>){++callback_calls;return 0;});\n    require(one.count_a==1&&one.queries==0&&one.total_query_length==0&&callback_calls==0,"singleton extension makes no query");\n}\nint main() {\n    const auto start=std::chrono::steady_clock::now();local_trees();invalid_inputs();all_static_small();all_adaptive_small();maximum_policy_witness();large_patterns();\n    require(max_queries==226,"maximum executed query count");\n    std::cout<<"{\\"checks\\":"<<checks<<",\\"staticCases\\":"<<static_cases<<",\\"localAssignments\\":"<<local_cases\n      <<",\\"adaptiveStates\\":"<<adaptive_states<<",\\"adaptiveLeaves\\":"<<adaptive_leaves<<",\\"budgetStates\\":"<<budget_states\n      <<",\\"totalQueries\\":"<<total_queries<<",\\"totalQueryLength\\":"<<total_lengths<<",\\"maxQueries\\":"<<max_queries\n      <<",\\"maxTotalQueryLengthObserved\\":"<<max_length<<",\\"provedTotalLengthBound\\":40306,\\"invalidCases\\":"<<invalid_cases\n      <<",\\"checksum\\":\\""<<checksum<<"\\",\\"seconds\\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\\n";\n}\n'
STANDALONE = '\n#include <climits>\n#include <iostream>\n#include <numeric>\nstd::uint64_t checks=0,cases=0,checksum=0;\nvoid verify(bool yes) { ++checks; if(!yes)throw std::logic_error("standalone callback failure"); }\n// Deliberately no use_machine declaration/definition and no count_mushrooms use.\n// Copying the whole visible fence must link with an ordinary callback alone.\nvoid run(const std::vector<int>& species) {\n    const int n=static_cast<int>(species.size());std::size_t calls=0,length=0;\n    auto machine=[&](const std::vector<int>& query) {\n        ++calls;length+=query.size();verify(query.size()>=2&&query.size()<=species.size());\n        auto unique=query;std::sort(unique.begin(),unique.end());\n        verify(std::adjacent_find(unique.begin(),unique.end())==unique.end());\n        int changes=0;\n        for(std::size_t i=0;i<query.size();++i){verify(query[i]>=0&&query[i]<n);if(i)changes+=species[query[i-1]]!=species[query[i]];}\n        return changes;\n    };\n    const auto answer=count_two_species_from_transition_queries(n,machine);\n    verify(answer.count_a==std::count(species.begin(),species.end(),0));\n    verify(answer.queries==calls&&answer.total_query_length==length&&calls<=226&&length<=40306);\n    checksum=checksum*1000003+static_cast<unsigned>(answer.count_a)+calls*100003+length;++cases;\n}\nint main() {\n    for(int n=1;n<=12;++n)for(unsigned mask=0;mask<(1u<<(n-1));++mask){\n        std::vector<int> species(n,0);for(int i=1;i<n;++i)species[i]=(mask>>(i-1))&1u;run(species);\n    }\n    for(int pattern=0;pattern<4;++pattern){std::vector<int> species(20000,0);\n        for(int i=1;i<20000;++i)species[i]=pattern==0?0:pattern==1?1:pattern==2?(i&1):((i/11)&1);\n        run(species);\n    }\n    bool invalid=false;int calls=0;\n    try{(void)count_two_species_from_transition_queries(INT_MAX,[&](std::vector<int>){++calls;return 0;});}\n    catch(const std::invalid_argument&){invalid=true;}\n    verify(invalid&&calls==0);\n    std::cout<<"{\\"cases\\":"<<cases<<",\\"checks\\":"<<checks<<",\\"checksum\\":\\""<<checksum<<"\\",\\"graderMacro\\":false,\\"machineStub\\":false}\\n";\n}\n'
args=[arg for arg in sys.argv[1:] if arg!='--sanitize']
article=Path(args[0]) if args else Path(__file__).resolve().parents[1] / 'src/content/docs/techniques/interactive-transition-count-species-decision-trees.mdx'
blocks=re.findall(r'^```cpp\s*\n(.*?)^```\s*$',article.read_text(),re.M|re.S)
if len(blocks)!=1:raise RuntimeError('expected one complete visible C++20 fence')
with tempfile.TemporaryDirectory(prefix='flowchartcp-mushrooms-') as directory:
    source=Path(directory)/'check.cpp';binary=Path(directory)/'check';source.write_text(blocks[0]+'\n'+HARNESS)
    flags=['-std=c++20','-O2','-Wall','-Wextra','-Werror'];environment=os.environ.copy()
    if '--sanitize' in sys.argv:
        flags+=['-O1','-g','-fsanitize=address,undefined','-fno-omit-frame-pointer']
        environment['ASAN_OPTIONS']='detect_leaks=0:halt_on_error=1';environment['UBSAN_OPTIONS']='halt_on_error=1'
    compiler=environment.get('CXX') or shutil.which('g++') or shutil.which('clang++') or 'c++'
    subprocess.run([compiler,*flags,'-DTWO_SPECIES_IOI_GRADER',str(source),'-o',str(binary)],check=True,timeout=120)
    timer=Path('/usr/bin/time')
    command=[str(timer),'-f','peak_rss_kib=%M',str(binary)] if timer.exists() and sys.platform.startswith('linux') else [str(binary)]
    run=subprocess.run(command,check=True,text=True,capture_output=True,env=environment,timeout=240)
    report=json.loads(run.stdout);match=re.search(r'^peak_rss_kib=(\d+)$',run.stderr,re.M)
    if match:report['peakRSSKiB']=int(match[1])
    report.update(article=str(article),sanitized='--sanitize' in sys.argv)
    standalone_source=Path(directory)/'standalone.cpp';standalone_binary=Path(directory)/'standalone'
    standalone_source.write_text(blocks[0]+'\n'+STANDALONE)
    subprocess.run([compiler,*flags,str(standalone_source),'-o',str(standalone_binary)],check=True,timeout=120)
    independent=subprocess.run([str(standalone_binary)],check=True,text=True,capture_output=True,env=environment,timeout=120)
    report['standaloneCallback']=json.loads(independent.stdout)
    report['graderAdapterMacro']='TWO_SPECIES_IOI_GRADER'
    print(json.dumps(report,ensure_ascii=False,indent=2))
